﻿/*jshint camelcase: false */

'use strict';

define(['jquery'], function ($) {

    const methods = {
        init: function(inputOptions) {
            const defaults = {
                menuWidth: 260,
                edge: 'left',
                closeOnClick: false
            };
            const options = $.extend(defaults, inputOptions);

            $(this).each(function () {
                const $this = $(this);

                // Touch Event
                let menuOut = false;

                const menu_id = $('#' + $this.attr('data-activates'));

                // Set to width
                if (options.menuWidth !== 260) {
                    menu_id.css('width', options.menuWidth);
                }

                // Add Touch Area
                const dragTarget = $('<div class="drag-target"></div>');
                $('body').append(dragTarget);

                if (options.edge === 'left') {
                    menu_id.css('transform', 'translateX(-100%)');
                    dragTarget.css({ 'left': 0 }); // Add Touch Area
                } else {
                    menu_id.addClass('right-aligned') // Change text-alignment to right
                    .css('transform', 'translateX(100%)');
                    dragTarget.css({ 'right': 0 }); // Add Touch Area
                }

                // If fixed sidenav, bring menu out
                if (menu_id.hasClass('fixed')) {
                    if (window.innerWidth > 992) {
                        menu_id.css('transform', 'translateX(0)');
                    } else {
                        $('body').removeClass('site-menubar-fold');
                    }
                }

                // Window resize to reset on large screens fixed
                if (menu_id.hasClass('fixed')) {
                    $(window).resize(function () {
                        if ($('body').hasClass('site-menubar-fold')) {
                            $('.site-menu li.has-sub').removeClass('active');
                            $('.site-menu .menu-item .collapsible-header').removeClass('active');
                            $('.site-menu .menu-item div.collapsible-body').css('display', 'none');
                        }
                        if (window.innerWidth > 992) {
                            // Close menu if window is resized bigger than 992 and user has fixed sidenav
                            if ($('#sidenav-overlay').length !== 0 && menuOut) {
                                removeMenu(true);
                            } else {
                                // menu_id.removeAttr('style');
                                menu_id.css('transform', 'translateX(0%)');
                                // menu_id.css('width', options.menuWidth);
                            }
                        } else if (menuOut === false) {

                            if (options.edge === 'left') {
                                menu_id.css('transform', 'translateX(-100%)');
                            } else {
                                menu_id.css('transform', 'translateX(100%)');
                            }
                        }
                    });
                }

                // if closeOnClick, then add close event for all a tags in side sideNav
                if (options.closeOnClick === true) {
                    menu_id.on('click.itemclick', 'a:not(.collapsible-header)', function () {
                        removeMenu();
                    });
                }

                function removeMenu(restoreNav) {
                    menuOut = false;
                    // Reenable scrolling
                    $('body').css({
                        overflow: '',
                        width: ''
                    });

                    $('#sidenav-overlay').velocity({ opacity: 0 }, {
                        duration: 200,
                        queue: false, easing: 'easeOutQuad',
                        complete: function() {
                            $(this).remove();
                        }
                    });
                    if (options.edge === 'left') {
                        // Reset phantom div
                        dragTarget.css({ width: '', right: '', left: '0' });
                        menu_id.velocity({ 'translateX': '-100%' }, {
                            duration: 200,
                            queue: false,
                            easing: 'easeOutCubic',
                            complete: function() {
                                if (restoreNav === true) {
                                    // Restore Fixed sidenav
                                    menu_id.removeAttr('style');
                                    menu_id.css('width', options.menuWidth);
                                }
                            }

                        });
                    } else {
                        // Reset phantom div
                        dragTarget.css({ width: '', right: '0', left: '' });
                        menu_id.velocity({ 'translateX': '100%' }, {
                            duration: 200,
                            queue: false,
                            easing: 'easeOutCubic',
                            complete: function() {
                                if (restoreNav === true) {
                                    // Restore Fixed sidenav
                                    menu_id.removeAttr('style');
                                    menu_id.css('width', options.menuWidth);
                                }
                            }
                        });
                    }
                }

                dragTarget.on('click', function () {
                    if (menuOut) {
                        removeMenu();
                    }
                });

                dragTarget.hammer({
                    prevent_default: false
                }).bind('pan', function (e) {

                    if (e.gesture.pointerType === 'touch') {

                        let x = e.gesture.center.x;

                        // Disable Scrolling
                        const $body = $('body');
                        const oldWidth = $body.innerWidth();
                        $body.css('overflow', 'hidden');
                        $body.width(oldWidth);

                        // If overlay does not exist, create one and if it is clicked, close menu
                        if ($('#sidenav-overlay').length === 0) {
                            const overlay = $('<div id="sidenav-overlay"></div>');
                            overlay.css('opacity', 0).click(function () {
                                removeMenu();
                            });
                            $('body').append(overlay);
                        }

                        // Keep within boundaries
                        if (options.edge === 'left') {
                            if (x > options.menuWidth) {
                                x = options.menuWidth;
                            } else if (x < 0) {
                                x = 0;
                            }
                        }

                        if (options.edge === 'left') {
                            // Left Direction
                            if (x < options.menuWidth / 2) {
                                menuOut = false;
                            }
                                // Right Direction
                            else if (x >= options.menuWidth / 2) {
                                menuOut = true;
                            }
                            menu_id.css('transform', 'translateX(' + (x - options.menuWidth) + 'px)');
                        } else {
                            // Left Direction
                            if (x < window.innerWidth - options.menuWidth / 2) {
                                menuOut = true;
                            }
                                // Right Direction
                            else if (x >= window.innerWidth - options.menuWidth / 2) {
                                menuOut = false;
                            }
                            let rightPos = x - options.menuWidth / 2;
                            if (rightPos < 0) {
                                rightPos = 0;
                            }

                            menu_id.css('transform', 'translateX(' + rightPos + 'px)');
                        }

                        // Percentage overlay
                        let overlayPerc;
                        if (options.edge === 'left') {
                            overlayPerc = x / options.menuWidth;
                            $('#sidenav-overlay').velocity({ opacity: overlayPerc }, { duration: 10, queue: false, easing: 'easeOutQuad' });
                        } else {
                            overlayPerc = Math.abs((x - window.innerWidth) / options.menuWidth);
                            $('#sidenav-overlay').velocity({ opacity: overlayPerc }, { duration: 10, queue: false, easing: 'easeOutQuad' });
                        }
                    }
                }).bind('panend', function (e) {

                    if (e.gesture.pointerType === 'touch') {
                        const velocityX = e.gesture.velocityX;
                        const x = e.gesture.center.x;
                        let leftPos = x - options.menuWidth;
                        let rightPos = x - options.menuWidth / 2;
                        if (leftPos > 0) {
                            leftPos = 0;
                        }
                        if (rightPos < 0) {
                            rightPos = 0;
                        }

                        if (options.edge === 'left') {
                            // If velocityX <= 0.3 then the user is flinging the menu closed so ignore menuOut
                            if (menuOut && velocityX <= 0.3 || velocityX < -0.5) {
                                // Return menu to open
                                if (leftPos !== 0) {
                                    menu_id.velocity({ 'translateX': [0, leftPos] }, { duration: 300, queue: false, easing: 'easeOutQuad' });
                                }

                                $('#sidenav-overlay').velocity({ opacity: 1 }, { duration: 50, queue: false, easing: 'easeOutQuad' });
                                dragTarget.css({ width: '50%', right: 0, left: '' });
                                menuOut = true;
                            } else if (!menuOut || velocityX > 0.3) {
                                // Enable Scrolling
                                $('body').css({
                                    overflow: '',
                                    width: ''
                                });
                                // Slide menu closed
                                menu_id.velocity({
                                    'translateX': [-1 * options.menuWidth - 10, leftPos]
                                }, {
                                    duration: 200,
                                    queue: false,
                                    easing: 'easeOutQuad'
                                });
                                $('#sidenav-overlay').velocity({ opacity: 0 }, {
                                    duration: 200, queue: false, easing: 'easeOutQuad',
                                    complete: function() {
                                        $(this).remove();
                                    }
                                });
                                dragTarget.css({ width: '10px', right: '', left: 0 });
                            }
                        } else {
                            if (menuOut && velocityX >= -0.3 || velocityX > 0.5) {
                                // Return menu to open
                                if (rightPos !== 0) {
                                    menu_id.velocity({ 'translateX': [0, rightPos] }, { duration: 300, queue: false, easing: 'easeOutQuad' });
                                }

                                $('#sidenav-overlay').velocity({ opacity: 1 }, { duration: 50, queue: false, easing: 'easeOutQuad' });
                                dragTarget.css({ width: '50%', right: '', left: 0 });
                                menuOut = true;
                            } else if (!menuOut || velocityX < -0.3) {
                                // Enable Scrolling
                                $('body').css({
                                    overflow: '',
                                    width: ''
                                });

                                // Slide menu closed
                                menu_id.velocity({ 'translateX': [options.menuWidth + 10, rightPos] }, { duration: 200, queue: false, easing: 'easeOutQuad' });
                                $('#sidenav-overlay').velocity({ opacity: 0 }, {
                                    duration: 200, queue: false, easing: 'easeOutQuad',
                                    complete: function() {
                                        $(this).remove();
                                    }
                                });
                                dragTarget.css({ width: '10px', right: 0, left: '' });
                            }
                        }
                    }
                });

                $this.click(function () {
                    const $body = $('body');
                    const $submenu = $('.site-menu .menu-item div.collapsible-body');
                    const menuCollapse = $body.hasClass('site-menubar-fold');

                    if (window.innerWidth > 992) {
                        $('.site-menu li.has-sub').removeClass('active');
                        $('.site-menu .menu-item .collapsible-header').removeClass('active');
                        $submenu.css('display', 'none');
                        menu_id.removeAttr('style');
                        $body.toggleClass('site-menubar-fold', !menuCollapse);
                    } else {

                        if (menuOut === true) {
                            menuOut = false;
                            removeMenu();
                        } else {
                            // Disable Scrolling
                            const oldWidth = $body.innerWidth();
                            $body.css('overflow', 'hidden');
                            $body.width(oldWidth);

                            // Push current drag target on top of DOM tree
                            $('body').append(dragTarget);

                            if (options.edge === 'left') {
                                dragTarget.css({ width: '50%', right: 0, left: '' });
                                menu_id.velocity({ 'translateX': [0, -1 * options.menuWidth] }, { duration: 300, queue: false, easing: 'easeOutQuad' });
                            } else {
                                dragTarget.css({ width: '50%', right: '', left: 0 });
                                menu_id.velocity({ 'translateX': [0, options.menuWidth] }, { duration: 300, queue: false, easing: 'easeOutQuad' });
                            }

                            const overlay = $('<div id="sidenav-overlay"></div>');
                            overlay.css('opacity', 0).click(function () {
                                menuOut = false;
                                removeMenu();
                                overlay.velocity({ opacity: 0 }, {
                                    duration: 300, queue: false, easing: 'easeOutQuad',
                                    complete: function() {
                                        $(this).remove();
                                    }
                                });
                            });
                            $body.append(overlay);
                            overlay.velocity({ opacity: 1 }, {
                                duration: 300, queue: false, easing: 'easeOutQuad',
                                complete: function() {
                                    menuOut = true;
                                }
                            });
                        }
                    }

                    if (menuCollapse) {
                        $submenu.mCustomScrollbar('destroy');
                    } else {
                        $submenu.mCustomScrollbar({ theme: 'minimal-dark' });
                    }

                    return false;
                });
            });
        },
        show: function() {
            this.trigger('click');
        },
        hide: function() {
            $('#sidenav-overlay').trigger('click');
        }
    };

    $.fn.sideNav2 = function (methodOrOptions) {
        if (methods[methodOrOptions]) {
            return methods[methodOrOptions].apply(this, Array.prototype.slice.call(arguments, 1));
        } else if (typeof methodOrOptions === 'object' || !methodOrOptions) {
            // Default to 'init'
            return methods.init.apply(this, arguments);
        } else {
            $.error('Method ' + methodOrOptions + ' does not exist on jQuery.sideNav');
        }
    }; // Plugin end
});

$(document).ready(function () {
    $('.toggleMenubar').sideNav2();
});

